/* Dark mode for every Puffy component, in every theme.
   Put data-glass-mode="dark" on <html> or any wrapper. Load this file last,
   after the theme files. The brand colour stays; surfaces turn charcoal,
   text turns light and shadows deepen. Selectors repeat a class here and
   there so they win over the theme files without !important. */
/* The theme files set their own text colour, so dark mode restates it on them too */
:is([data-glass-mode="dark"], .dark),
:is([data-glass-mode="dark"], .dark) [data-glass-theme],
:is([data-glass-mode="dark"], .dark)[data-glass-theme] {
  --glass-fg: #f2f2f5;
  --glass-shadow: 232 234 242; /* hairlines and quiet text, now light */
  --glass-danger: #ff7a84;
  --gd-surface: #1c1c20;
  --gd-raised: #26262b;
  --gd-hover: #2f2f35;
  --gd-line: rgb(255 255 255 / 0.12);
  --gd-drop: rgb(0 0 0 / 0.55);
  color-scheme: dark;
}

/* ---------- Buttons ---------- */
:is([data-glass-mode="dark"], .dark) .gb.gb:not([data-variant="ghost"]) { --gb-drop: var(--gd-drop); }
:is([data-glass-mode="dark"], .dark) .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"] { --gb-fill: var(--gd-raised); --gb-ring: var(--gd-line); --gb-fg: var(--glass-fg); }
:is([data-glass-mode="dark"], .dark) .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"]:hover:not(:disabled) { --gb-fill: var(--gd-hover); }
:is([data-glass-mode="dark"], .dark) .gb.gb.gb.gb[data-effect="flat"][data-variant="secondary"]:active:not(:disabled) { --gb-fill: #38383f; }
:is([data-glass-mode="dark"], .dark) .gb.gb.gb:is([data-effect="glass"], [data-effect="bubble"])[data-variant="secondary"] {
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.16), rgb(255 255 255 / 0.05));
  --gb-fg: var(--glass-fg);
  --gb-ring: rgb(255 255 255 / 0.14);
  --gb-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.22);
  --gb-rim-hi: rgb(255 255 255 / 0.5);
  --gb-rim-lo: rgb(255 255 255 / 0.06);
  background: var(--gb-fill);
}
:is([data-glass-mode="dark"], .dark) .gb.gb.gb[data-effect="bubble"][data-variant="secondary"] {
  --gb-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.35), inset 0 8px 10px -7px rgb(255 255 255 / 0.3), inset 0 -8px 12px -7px rgb(0 0 0 / 0.4);
}
/* Mist: the soft slate main button turns to a deep slate */
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"],
:is([data-glass-mode="dark"], .dark)[data-glass-tint="frost"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"] { --gb-fill: #3a404b; --gb-fg: #eef1f6; }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gb.gb.gb.gb[data-effect="flat"][data-variant="primary"]:hover:not(:disabled) { --gb-fill: #444b57; }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gb.gb.gb[data-variant="primary"]:is([data-effect="glass"], [data-effect="bubble"]) {
  --gb-fg: #f2f4f8;
  --gb-fill: linear-gradient(180deg, rgb(255 255 255 / 0.22), rgb(255 255 255 / 0.08) 50%, rgb(255 255 255 / 0.14));
  --gb-inset: inset 0 1px 0 0 rgb(255 255 255 / 0.4), inset 0 -1px 0 0 rgb(255 255 255 / 0.1);
  --gb-ring: rgb(255 255 255 / 0.18);
}

/* ---------- Fields, menus, cards ---------- */
:is([data-glass-mode="dark"], .dark) .gf.gf { --gf-fill: var(--gd-surface); --gf-ring: var(--gd-line); --gf-inset: inset 0 0 0 0 transparent; }
:is([data-glass-mode="dark"], .dark) .gf.gf:is([data-effect="glass"], [data-effect="bubble"]) { --gf-fill: linear-gradient(180deg, rgb(255 255 255 / 0.1), rgb(255 255 255 / 0.04)); --gf-rim-hi: rgb(255 255 255 / 0.4); --gf-rim-lo: rgb(255 255 255 / 0.05); }
:is([data-glass-mode="dark"], .dark) .gf.gf:focus-within, :is([data-glass-mode="dark"], .dark) .gf.gf[data-open] { --gf-ring: color-mix(in srgb, var(--glass-tint) 70%, #fff); --gf-halo: color-mix(in srgb, var(--glass-tint) 25%, transparent); }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gf.gf:focus-within, :is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gf.gf[data-open] { --gf-ring: rgb(255 255 255 / 0.4); --gf-halo: rgb(255 255 255 / 0.08); }
:is([data-glass-mode="dark"], .dark) .gp.gp {
  --gp-fill: var(--gd-raised);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px var(--gd-line), 0 20px 44px -16px rgb(0 0 0 / 0.7);
}
:is([data-glass-mode="dark"], .dark) .gp.gp:is([data-effect="glass"], [data-effect="bubble"]) { --gp-fill: rgb(38 38 44 / 0.72); }
:is([data-glass-mode="dark"], .dark) .gp.gp .gp-hl { background: rgb(255 255 255 / 0.09); box-shadow: inset 0 0 0 0.5px rgb(255 255 255 / 0.08); }
:is([data-glass-mode="dark"], .dark) .gp.gp .gp-check { color: color-mix(in srgb, var(--glass-tint) 60%, #fff); }
:is([data-glass-mode="dark"], .dark) .gc.gc { --gc-fill: var(--gd-surface); --gc-ring: var(--gd-line); --gc-drop: 0 14px 30px -18px rgb(0 0 0 / 0.7); }
:is([data-glass-mode="dark"], .dark) .gc.gc[data-level="2"] { --gc-fill: rgb(255 255 255 / 0.04); }
:is([data-glass-mode="dark"], .dark) .gc.gc:is([data-effect="glass"], [data-effect="bubble"]) { --gc-fill: linear-gradient(180deg, rgb(255 255 255 / 0.1), rgb(255 255 255 / 0.04)); --gc-rim-hi: rgb(255 255 255 / 0.4); --gc-rim-lo: rgb(255 255 255 / 0.05); }

/* ---------- Display parts ---------- */
:is([data-glass-mode="dark"], .dark) .gtb { background: var(--gd-surface); box-shadow: 0 0 0 1px var(--gd-line); }
:is([data-glass-mode="dark"], .dark) .gbn { background: var(--gd-surface); box-shadow: 0 0 0 1px var(--gd-line), 0 10px 24px -16px rgb(0 0 0 / 0.7); }
:is([data-glass-mode="dark"], .dark) .gdl { background: var(--gd-raised); box-shadow: 0 0 0 1px var(--gd-line), 0 30px 60px -20px rgb(0 0 0 / 0.8); }
:is([data-glass-mode="dark"], .dark) .gtabs-pill.gtabs-pill { background: #3a3a41; box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.08), 0 1px 3px rgb(0 0 0 / 0.5); }
:is([data-glass-mode="dark"], .dark) .gtabs.gtabs:not([data-variant="subtle"]) { background: rgb(255 255 255 / 0.07); box-shadow: none; }
:is([data-glass-mode="dark"], .dark) .gtabs.gtabs[data-variant="subtle"] .gtabs-pill { background: rgb(255 255 255 / 0.1); box-shadow: none; }
:is([data-glass-mode="dark"], .dark) .gtab.gtab[aria-selected="true"] { color: var(--glass-fg); }
:is([data-glass-mode="dark"], .dark) .gtt-tip.gtt-tip { color: #f2f2f5; background: #34343b; box-shadow: 0 0 0 1px var(--gd-line), 0 8px 20px -8px rgb(0 0 0 / 0.7); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd[data-tone="neutral"] { --gbd-c: rgb(255 255 255 / 0.8); --gbd-bg: rgb(255 255 255 / 0.1); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd[data-tone="accent"] { --gbd-c: color-mix(in srgb, var(--glass-tint) 55%, #fff); --gbd-bg: color-mix(in srgb, var(--glass-tint) 24%, transparent); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd[data-tone="success"] { --gbd-c: #5fd39a; --gbd-bg: rgb(23 160 101 / 0.18); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd[data-tone="warning"] { --gbd-c: #f2b84b; --gbd-bg: rgb(224 154 22 / 0.18); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd[data-tone="danger"] { --gbd-c: #ff8a93; --gbd-bg: rgb(209 44 58 / 0.22); }
:is([data-glass-mode="dark"], .dark) .gbd.gbd { box-shadow: none; background: var(--gbd-bg); }

/* ---------- Controls ---------- */
:is([data-glass-mode="dark"], .dark) .gck.gck { background: var(--gd-surface); box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.22); }
:is([data-glass-mode="dark"], .dark) .gopt input:checked + .gck.gck { background: var(--glass-tint); box-shadow: none; }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gopt input:checked + .gck.gck { background: #c9d0db; color: #1f2633; }
:is([data-glass-mode="dark"], .dark) .gsw-track.gsw-track { background: rgb(255 255 255 / 0.16); box-shadow: none; }
:is([data-glass-mode="dark"], .dark) .gsw[aria-checked="true"] .gsw-track.gsw-track { background: var(--glass-tint); }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] .gsw[aria-checked="true"] .gsw-track.gsw-track { background: #7d8798; }
:is([data-glass-mode="dark"], .dark) .gsl-track.gsl-track { background: rgb(255 255 255 / 0.08); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.4); }
:is([data-glass-mode="dark"], .dark) .gsl-dots i:not([data-on]) { background: rgb(255 255 255 / 0.25); }

/* ---------- Over a dark picture, solid parts are dark too ---------- */
:is([data-glass-mode="dark"], .dark) [data-glass-on="dark"] :is(.gf, .gc, .gp, .gtb, .gbn, .gdl, .gbd, .gtt-tip, .gb:not([data-variant="ghost"])) { --glass-fg: #f2f2f5; --glass-shadow: 232 234 242; --glass-danger: #ff7a84; }

/* Text-only buttons always take the page's text colour in the dark */
:is([data-glass-mode="dark"], .dark) .gb.gb.gb.gb[data-variant="ghost"] { --gb-fg: var(--glass-fg); }
/* Badges on a dark picture in dark mode: a soft see-through chip, light text */
:is([data-glass-mode="dark"], .dark) [data-glass-on="dark"] .gbd:is([data-tone="neutral"], [data-tone="accent"]):not([data-effect="glass"]):not([data-effect="bubble"]) { --gbd-bg: rgb(255 255 255 / 0.16); }

/* Puffy's main button is filled with deep liquid colour, so it keeps white
   ink in every mode and on any picture */
[data-glass-theme="puffy"] .gb.gb.gb.gb.gb[data-variant="primary"]:not([data-effect="flat"]),
[data-glass-theme="puffy"] .gb.gb.gb.gb.gb[data-variant="primary"][data-effect="flat"] { --gb-fg: #fff; color: #fff; }
/* The active card stays a light pastel, so it keeps dark ink */
[data-glass-theme="puffy"] .gc.gc.gc.gc[data-effect][data-active] { --glass-fg: #1f1a2e; --glass-shadow: 31 26 46; color: #1f1a2e; }
/* …but dark secondary buttons inside those cards keep light ink */
:is(:is([data-glass-mode="dark"], .dark), [data-glass-on="dark"]) [data-glass-theme="puffy"] .gc[data-active] .gb.gb.gb.gb.gb[data-variant="secondary"] { --glass-fg: #f2f2f5; --gb-fg: #f2f2f5; color: #f2f2f5; }

/* Progress tracks stay visible on dark pages */
:root:is([data-glass-mode="dark"], .dark) .gpr-track, :root:is([data-glass-mode="dark"], .dark) [data-glass-theme] .gpr-track { --gpr-track: rgb(255 255 255 / 0.12); }
:root:is([data-glass-mode="dark"], .dark) .gus .gpr-track { --gpr-track: rgb(255 255 255 / 0.12); box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.05); }

:is([data-glass-mode="dark"], .dark) .gth-label { background-image: linear-gradient(90deg, rgb(255 255 255 / 0.5) 30%, var(--gth-c) 46%, #fff 50%, var(--gth-c) 54%, rgb(255 255 255 / 0.5) 70%); }
